<?php declare(strict_types=1); ?>
<!doctype html><html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Takvim senkronizasyonu</title><style>body{font-family:system-ui;background:#f5f7f5;color:#26332b;margin:0}.wrap{max-width:980px;margin:32px auto;padding:0 16px}.panel{background:#fff;padding:22px;border-radius:14px;margin:14px 0}.muted{color:#68756c}.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block;font-size:13px;font-weight:700}input{display:block;width:100%;padding:11px;border:1px solid #dfe6e0;border-radius:8px;margin-top:6px;box-sizing:border-box}button,.btn{display:inline-block;background:#176b50;color:#fff;padding:10px 14px;border:0;border-radius:8px;text-decoration:none;font-weight:700;cursor:pointer}.danger{background:#a43}.feed{border:1px solid #e8eee9;border-radius:10px;padding:14px;margin:10px 0}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.notice{padding:12px;background:#eff8f1;border:1px solid #cde7d2;border-radius:8px;overflow-wrap:anywhere}.error{background:#fff1ef;border-color:#f0c9c3}@media(max-width:650px){.grid{grid-template-columns:1fr}.panel{padding:15px}}</style><?php require APP_ROOT . '/views/site/partials/account-theme.php'; ?></head><body><main class="wrap"><p><a href="/vendor/properties/<?= (int)$property['id'] ?>/availability">← Müsaitlik takvimine dön</a></p><h1>Takvim senkronizasyonu</h1><p class="muted"><?= e($property['title']) ?> · Airbnb, Booking.com ve diğer iCal destekli platformlar</p>
<?php if(!empty($calendarMessage)): ?><div class="notice <?= ($calendarMessageType??'success')==='error'?'error':'' ?>" role="status"><?= e($calendarMessage) ?></div><?php endif; ?>
<?php if(!empty($newExportUrl)): ?><section class="panel"><h2>Dışa aktarma bağlantınız hazır</h2><p class="muted">Bu bağlantıyı Airbnb veya Booking.com içindeki takvim içe aktarma alanına ekleyin. Bağlantıyı güvenli yerde saklayın.</p><div class="notice"><?= e($newExportUrl) ?></div><button type="button" onclick="navigator.clipboard&&navigator.clipboard.writeText(<?= json_encode($newExportUrl) ?>)">Bağlantıyı kopyala</button></section><?php endif; ?>
<section class="panel"><h2>Harici takvim ekle</h2><p class="muted">Platformunuzun iCal/ICS dışa aktarma adresini girin. Kaynak adres şifreli saklanır; yalnızca HTTPS bağlantıları kabul edilir.</p><form method="post" action="/vendor/properties/calendar-feed/add" class="grid"><?= csrf_field() ?><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"><label>Takvim adı<input name="label" maxlength="120" required placeholder="Airbnb takvimi"></label><label>iCal / ICS URL<input name="url" type="url" maxlength="2048" required placeholder="https://.../calendar.ics"></label><div><button type="submit">Takvimi ekle</button></div></form></section>
<section class="panel"><h2>Bu ilana bağlı takvimler</h2><?php if(empty($feeds)): ?><p class="muted">Henüz harici takvim veya dışa aktarma bağlantısı yok.</p><?php else: ?><?php foreach($feeds as $feed): ?><div class="feed"><strong><?= e($feed['label']) ?></strong> · <?= $feed['direction']==='import'?'İçe aktarma':'Dışa aktarma' ?><p class="muted">Durum: <?= e($feed['last_sync_status']??($feed['direction']==='export'?'Bağlantı hazır':'Henüz eşitlenmedi')) ?> · Son eşitleme: <?= !empty($feed['last_synced_at'])?e(date('d.m.Y H:i',strtotime($feed['last_synced_at']))):'—' ?></p><?php if(!empty($feed['last_sync_message'])): ?><p class="muted"><?= e($feed['last_sync_message']) ?></p><?php endif; ?>
<?php if(!empty($syncLogsByFeed[(int)$feed['id']])): ?><details style="margin:10px 0"><summary>Son senkronizasyon geçmişi</summary><?php foreach($syncLogsByFeed[(int)$feed['id']] as $log): ?><p class="muted"><?= e(date('d.m.Y H:i',strtotime($log['started_at']))) ?> · <?= e($log['status']) ?> · <?= (int)$log['event_count'] ?> etkinlik · <?= (int)$log['blocked_count'] ?> engel · <?= (int)$log['conflict_count'] ?> çakışma<?= !empty($log['error_message'])?' · '.e($log['error_message']):'' ?></p><?php endforeach; ?></details><?php endif; ?>
<div class="actions"><?php if($feed['direction']==='import'): ?><form method="post" action="/vendor/properties/calendar-feed/sync"><?= csrf_field() ?><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"><input type="hidden" name="feed_id" value="<?= (int)$feed['id'] ?>"><button type="submit">Şimdi eşitle</button></form><?php endif; ?><form method="post" action="/vendor/properties/calendar-feed/delete" onsubmit="return confirm('Bu takvim kaldırılsın mı? İçe aktarılan tarih blokları da silinir.')"><?= csrf_field() ?><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"><input type="hidden" name="feed_id" value="<?= (int)$feed['id'] ?>"><button class="danger" type="submit">Kaldır</button></form></div></div><?php endforeach; ?><?php endif; ?><form method="post" action="/vendor/properties/calendar-feed/export" style="margin-top:16px"><?= csrf_field() ?><input type="hidden" name="property_id" value="<?= (int)$property['id'] ?>"><button type="submit">Yeni dışa aktarma bağlantısı oluştur</button></form></section>
<section class="panel"><h2>Otomatik eşitleme</h2><p class="muted">Yönetici panelindeki Takvim Senkronizasyonu sayfasında gösterilen güvenli Cron URL'sini cPanel Cron Jobs bölümüne ekleyin. Önerilen aralık 30 dakikadır.</p><a class="btn" href="/admin/calendar-sync">Cron ayarları (yönetici)</a></section>
